const TTL_WITH_VERSION_MS = 10 * 60 * 1000; // invalidado na hora pela versão
const TTL_WITHOUT_VERSION_MS = 60 * 1000;   // metafield ainda não gravado

function getCachedFlags(shop, version) {
  try {
    const raw = sessionStorage.getItem(`flags_app_${shop}`);
    if (!raw) return null;
    const cached = JSON.parse(raw);
    if (cached.version !== version || Date.now() > cached.expiresAt) return null;
    return cached.flags;
  } catch (e) {
    return null; // sessionStorage pode falhar em modo privado
  }
}

async function fetchFlags(shop, version) {
  const cached = getCachedFlags(shop, version);
  if (cached) return cached;
  try {
    // ?v= faz o App Proxy ignorar o cache do servidor quando a versão muda
    const url = version ? `/apps/flags?v=${encodeURIComponent(version)}` : "/apps/flags";
    const res = await fetch(url, { credentials: "same-origin" });
    if (!res.ok) return [];
    const flags = await res.json();
    setCachedFlags(shop, version, flags);
    return flags;
  } catch (e) {
    return []; // a loja nunca quebra por causa do app
  }
}

(function () {
  if (window.__flagsAppLoaded) return; // o embed pode ser incluído duas vezes
  window.__flagsAppLoaded = true;

  async function init() {
    const shopEl = document.querySelector(".flags-app-shop-data");
    if (!shopEl) return;

    const flags = await fetchFlags(shopEl.dataset.shopDomain, shopEl.dataset.flagsVersion || "");
    if (!flags.length) return;

    const render = () => {
      renderPdpBadges(flags);
      renderCardBadges(flags);
    };
    render();

    // filtros, "carregar mais" e scroll infinito adicionam cards depois
    let timer = null;
    const observer = new MutationObserver(() => {
      clearTimeout(timer);
      timer = setTimeout(render, 250);
    });
    observer.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();

function matchFlags(flags, { tags, collections, inventory, productId }) {
  const lowerTags = tags.map((t) => t.trim().toLowerCase());
  const lowerCollections = collections.map((c) => c.trim().toLowerCase());
  return flags
    .filter((flag) => {
      switch (flag.condition_type) {
        case "tag":
          return splitValues(flag.condition_value).some((t) => lowerTags.includes(t));
        case "collection":
          return splitValues(flag.condition_value).some((c) => lowerCollections.includes(c));
        case "stock":
          return inventory != null && inventory < parseInt(flag.condition_value, 10);
        case "products":
          return productId != null && parseProductIds(flag.condition_value).includes(String(productId));
        default:
          return false;
      }
    })
    .sort((a, b) => b.priority - a.priority);
}

// Seletores do título em ordem de preferência. Classes com "title" vêm por
// último porque também casam cópias (ex.: barra fixa de compra do Horizon).
const PDP_TITLE_SELECTORS = [
  "h1",
  "[role='heading'], h2, h3",
  "[class*='title' i], [class*='heading' i]",
];

function isUsableTitle(el) {
  if (el.closest(EXCLUDED_AREAS) || el.closest("a[href*='/products/']")) return false;
  if (el.closest("[class*='sticky' i]")) return false;
  const rect = el.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0; // ignora cópias escondidas
}

function findPdpAnchor(productTitle) {
  const scope = document.querySelector("main") || document.body;
  const wanted = normalizeText(productTitle); // título vindo do Liquid
  if (wanted) {
    for (const selector of PDP_TITLE_SELECTORS) {
      for (const el of scope.querySelectorAll(selector)) {
        if (normalizeText(el.textContent) === wanted && isUsableTitle(el)) return el;
      }
    }
  }
  return scope.querySelector("h1") || scope.querySelector("form[action*='/cart/add']");
}

function renderPdpBadges(flags) {
  const dataEl = document.querySelector(".flags-app-pdp-data");
  if (!dataEl) return;

  const title = findPdpAnchor(dataEl.dataset.productTitle);
  if (!title) return;
  // temas que re-renderizam a seção (troca de variante) removem o grupo,
  // por isso confere o vizinho em vez de um atributo
  const previous = title.previousElementSibling;
  if (previous && previous.classList.contains("fa-group--inline")) return;

  const inventoryRaw = dataEl.dataset.productInventory;
  const matches = matchFlags(flags, {
    tags: (dataEl.dataset.productTags || "").split(",").filter(Boolean),
    collections: (dataEl.dataset.productCollections || "").split(",").filter(Boolean),
    inventory: inventoryRaw === "" || inventoryRaw == null ? null : parseInt(inventoryRaw, 10),
    productId: dataEl.dataset.productId || null,
  });
  if (matches.length === 0) return;

  const group = document.createElement("div");
  group.className = "fa-group fa-group--inline";
  matches.forEach((flag) => group.appendChild(buildBadgeEl(flag)));
  title.parentNode.insertBefore(group, title);
}

const MAX_CARD_DEPTH = 8;

// Card = menor ancestral do link que tem imagem e só aponta para esse produto.
// Dawn: link no título; Horizon: <a class="product-card__link"> vazio por cima do card.
function findCard(anchor, handle) {
  if (anchor.querySelector("img")) return anchor;
  let node = anchor.parentElement;
  for (let depth = 0; node && node !== document.body && depth < MAX_CARD_DEPTH; depth++) {
    if (node.querySelector("img")) {
      const links = node.querySelectorAll('a[href*="/products/"]');
      const single = Array.from(links).every(
        (a) => extractHandle(a.getAttribute("href") || "") === handle,
      );
      return single ? node : null; // achou a grade inteira, não um card
    }
    node = node.parentElement;
  }
  return null;
}

async function renderCardBadges(flags) {
  // nos cards só temos tags e id (via /products/<handle>.js):
  // coleção e estoque baixo só funcionam na página de produto
  const cardFlags = flags.filter(
    (f) => f.condition_type === "tag" || f.condition_type === "products",
  );
  if (cardFlags.length === 0) return;

  const pdpData = document.querySelector(".flags-app-pdp-data");
  const currentHandle = pdpData ? pdpData.dataset.productHandle : null;
  const pending = [];

  document.querySelectorAll('a[href*="/products/"]').forEach((anchor) => {
    if (anchor.closest(EXCLUDED_AREAS)) return;
    const handle = extractHandle(anchor.getAttribute("href") || "");
    if (!handle || handle === currentHandle) return;
    const card = findCard(anchor, handle);
    if (!card) return;
    // um card tem vários links (imagem, título, overlay): processa uma vez só
    if (card.closest(`[${RENDERED_ATTR}]`) || card.querySelector(`[${RENDERED_ATTR}]`)) return;
    const root = findMediaBox(card);
    if (!root) return;
    card.setAttribute(RENDERED_ATTR, "");

    pending.push(
      fetchProduct(handle).then((product) => {
        if (!product) return;
        const matches = matchFlags(cardFlags, {
          tags: product.tags || [], collections: [], inventory: null, productId: product.id,
        });
        if (matches.length) renderOnCard(root, matches);
      }),
    );
  });
  await Promise.all(pending);
}

