// Força teste (BILLING_TEST=true) ou real (=false) para todas as lojas.
// Sem a variável, decide por loja.
const BILLING_TEST_OVERRIDE =
  process.env.BILLING_TEST === "true" ? true : process.env.BILLING_TEST === "false" ? false : null;

const devStoreCache = new Map(); // o tipo da loja não muda durante a sessão

async function isDevelopmentStore(admin, shop) {
  if (devStoreCache.has(shop)) return devStoreCache.get(shop);
  try {
    const response = await admin.graphql(`#graphql
      query ShopPlan { shop { plan { partnerDevelopment } } }`);
    const json = await response.json();
    const isDev = Boolean(json.data?.shop?.plan?.partnerDevelopment);
    devStoreCache.set(shop, isDev);
    return isDev;
  } catch (error) {
    console.error("Não foi possível consultar o tipo da loja:", await describeError(error));
    return process.env.NODE_ENV !== "production";
  }
}

export async function isTestBilling({ admin, session }) {
  if (BILLING_TEST_OVERRIDE != null) return BILLING_TEST_OVERRIDE;
  return isDevelopmentStore(admin, session.shop);
}

// DEPOIS: sempre inclui as de teste e prefere o plano mais alto
export async function getCurrentPlan(auth) {
  const isTest = await isTestBilling(auth);
  const { appSubscriptions } = await auth.billing.check({
    plans: [BASIC_PLAN, PRO_PLAN],
    isTest: true, // isTest no check só filtra; não muda a cobrança
  });
  const subscription =
    appSubscriptions?.find((s) => s.name === PRO_PLAN) ??
    appSubscriptions?.find((s) => s.name === BASIC_PLAN) ??
    null;
  const planName = subscription?.name ?? FREE_PLAN;
  return {
    planName,
    features: getPlanFeatures(planName),
    subscription,
    isTest: subscription?.test ?? isTest,
  };
}

export async function action({ request }) {
  const { billing, session, admin } = await authenticate.admin(request);
  const plan = (await request.formData()).get("plan");

  if (plan === BASIC_PLAN || plan === PRO_PLAN) {
    const isTest = await isTestBilling({ admin, session });
    // lança um Response que redireciona para a tela de aprovação da Shopify
    return await billing.request({ plan, isTest });
  }

  if (plan === FREE_PLAN) {
    const { subscription, isTest } = await getCurrentPlan({ admin, session, billing });
    if (subscription) {
      await billing.cancel({ subscriptionId: subscription.id, isTest, prorate: true });
    }
    // mantém ativa só a flag de maior prioridade (limite do plano grátis)
    const active = await prisma.flag.findMany({
      where: { shop: session.shop, active: true },
      orderBy: [{ priority: "desc" }, { createdAt: "desc" }],
      select: { id: true },
    });
    const extra = active.slice(PLANS[FREE_PLAN].maxActiveFlags).map((f) => f.id);
    if (extra.length) {
      await prisma.flag.updateMany({ where: { id: { in: extra } }, data: { active: false } });
      await syncFlagsToMetafield(admin, session.shop);
    }
    return json({ ok: true, deactivated: extra.length });
  }

  return json({ error: "Plano inválido" }, { status: 400 });
}

