/**
 * Texto legível de um erro da Admin API. A lib lança um Response (com o corpo
 * de erro da Shopify) em vez de um Error; aqui lemos esse corpo.
 */
export async function describeError(error) {
  if (error instanceof Response) {
    let body = "";
    try {
      body = await error.clone().text();
    } catch (e) {
      /* corpo já consumido */
    }
    return `HTTP ${error.status} ${body}`.trim();
  }
  // HttpResponseError da @shopify/shopify-api (ex.: billing.check)
  if (error?.response?.body) {
    return `HTTP ${error.response.code} ${JSON.stringify(error.response.body)}`;
  }
  return error?.message ?? String(error);
}

/**
 * Webhooks que não chamam a Admin API (desinstalação e compliance). O
 * authenticate.webhook da lib carrega e renova o token offline da loja; depois
 * da desinstalação a renovação é recusada e a lib responde 500.
 * Aqui só validamos a assinatura HMAC.
 */
export async function verifyWebhook(request) {
  if (request.method !== "POST") {
    throw new Response(undefined, { status: 405 });
  }
  const rawBody = await request.text();
  const received = Buffer.from(request.headers.get("X-Shopify-Hmac-Sha256") || "");
  const expected = Buffer.from(
    crypto
      .createHmac("sha256", process.env.SHOPIFY_API_SECRET || "")
      .update(rawBody, "utf8")
      .digest("base64"),
  );
  if (received.length !== expected.length || !crypto.timingSafeEqual(received, expected)) {
    throw new Response(undefined, { status: 401 });
  }

  const shop = request.headers.get("X-Shopify-Shop-Domain");
  // "shop/redact" -> "SHOP_REDACT", mesmo formato do topic da lib
  const topic = (request.headers.get("X-Shopify-Topic") || "").toUpperCase().replace(/[/.]/g, "_");
  if (!shop || !topic) {
    throw new Response(undefined, { status: 400 });
  }
  return { shop, topic, payload: JSON.parse(rawBody || "{}") };
}

