import { verifyWebhook } from "../shopify.server";
import prisma from "../db.server";

export const action = async ({ request }) => {
  const { shop } = await verifyWebhook(request);

  await prisma.session.deleteMany({ where: { shop } });
  await prisma.flag.deleteMany({ where: { shop } });
  await prisma.shopSettings.deleteMany({ where: { shop } });

  return new Response();
};

// app/routes/webhooks.compliance.jsx
// O app não guarda dados de clientes (só flags e configurações da loja).
export const action = async ({ request }) => {
  const { shop, topic } = await verifyWebhook(request);

  switch (topic) {
    case "CUSTOMERS_DATA_REQUEST":
    case "CUSTOMERS_REDACT":
      console.log(`[compliance] ${topic} de ${shop}: nenhum dado de cliente armazenado.`);
      break;
    case "SHOP_REDACT": // 48h depois da desinstalação
      await prisma.$transaction([
        prisma.flag.deleteMany({ where: { shop } }),
        prisma.shopSettings.deleteMany({ where: { shop } }),
        prisma.session.deleteMany({ where: { shop } }),
      ]);
      console.log(`[compliance] SHOP_REDACT: dados de ${shop} apagados.`);
      break;
    default:
      return new Response("Tópico não tratado", { status: 404 });
  }
  return new Response();
};

